const $=s=>document.querySelector(s),A=$('#app');let ME=null,META=null,poll=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast=m=>{const t=$('#toast');t.textContent=m;t.style.display='block';clearTimeout(t._);t._=setTimeout(()=>t.style.display='none',2600)};
async function api(u,o={}){const opt={method:o.method||(o.body?'POST':'GET'),headers:{}};if(o.body instanceof FormData)opt.body=o.body;else if(o.body){opt.body=JSON.stringify(o.body);opt.headers['Content-Type']='application/json'}
 const r=await fetch('/api'+u,opt);const j=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(j.message||j.error||'Error');e.code=j.error;e.status=r.status;throw e}return j}
const stars=n=>n==null?'<span class="muted">No ratings yet</span>':`<span class="stars">${'★'.repeat(Math.round(n))}${'☆'.repeat(5-Math.round(n))}</span> <b>${n}</b>`;
const av=(u,c='')=>u?.photo?`<img class="av ${c}" src="${u.photo}">`:`<div class="av ${c}">${esc((u?.name||'?')[0].toUpperCase())}</div>`;
const tm=t=>new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
let GEO=null;const geo=async()=>{if(GEO)return GEO;try{const r=await fetch('/geo.json',{credentials:'same-origin'});if(!r.ok)throw 0;GEO=await r.json()}catch(e){return GEO={countries:['South Africa'],areas:{'South Africa':PROV}},GEO}return GEO};const AREAS=c=>(GEO&&GEO.areas[c])||[];
const DISC='Swap at your own risk. Cannabis laws differ by country and region — only swap where it is legal for you. Bud Share does not allow sales.';
const discBox=()=>`<div class="disc">⚠️ ${DISC}</div>`;
const loc=u=>esc([u.town,u.province].filter(Boolean).join(', '))+((u.country||'South Africa')!=((ME&&ME.country)||'South Africa')?' · '+esc(u.country):'');
function areaField(c,v){const a=AREAS(c);return a.length?`<select name="province" required>${opts(a,v,'Choose…')}</select>`:`<input name="province" required placeholder="State / province / region" value="${esc(v||'')}">`}
function locFields(c='South Africa',v=''){return `<label>Country</label><select name="country" id="lc" required>${opts(GEO.countries,c)}</select><label>Area / region</label><div id="la">${areaField(c,v)}</div><label>Town / city</label>`}
function bindLoc(){const c=$('#lc');if(c)c.onchange=()=>{$('#la').innerHTML=areaField(c.value,'')}}
const PROV=['Eastern Cape','Free State','Gauteng','KwaZulu-Natal','Limpopo','Mpumalanga','North West','Northern Cape','Western Cape'];
const opts=(a,sel,blank)=>(blank?`<option value="">${blank}</option>`:'')+a.map(x=>`<option ${x==sel?'selected':''}>${x}</option>`).join('');
const LEAF=(c='lf')=>'<img src="/whoomph-leaf-fbfc610e.png" alt="" class="'+c+'">';
const BRAND=`<span class="brand"><b>Bud Share</b> <span class="tag">– craft growers network</span><small>By <img src="/whoomph-logo-b70b4539.png" alt="Whoomph" class="wlogo"></small></span>`;
function shell(title,body,tab,back){clearInterval(poll);document.body.classList.remove('in-chat');A.innerHTML=`<header>${back?`<button onclick="history.back()">‹</button>`:''}<h1>${title=='Bud Share'?BRAND:title}</h1></header>${body}`+(ME?`<nav>
 <a href="#/browse" class="${tab=='browse'?'on':''}"><span>${LEAF('lf-nav')}</span>Flower</a><a href="#/swaps" class="${tab=='swaps'?'on':''}"><span>💬</span>Swaps${ME.unread?`<i class="badge">${ME.unread}</i>`:''}</a>
 <a href="#/strains" class="${tab=='strains'?'on':''}"><span>${LEAF('lf-nav')}</span>My Strains</a><a href="#/profile" class="${tab=='profile'?'on':''}"><span>👤</span>Profile</a></nav>`:'')}
function reportModal(u,swapId){modal(`<h3>Report ${esc(u.name)}</h3><label>Reason</label><select name="reason" required>${opts(ME.reasons,'','Choose…')}</select><label>Note (optional)</label><textarea name="note"></textarea><p class="muted">Non-delivery reports count toward automatic removal (${META.reportLimit} strikes). Other reports go to the Bud Share admins.</p>`,'Send report',async d=>{try{d.swapId=swapId;const r=await api(`/users/${u.id}/report`,{body:d});toast(r.removed?'Reported – member removed':'Report sent')}catch(e){toast(e.message)}},'red')}
async function admMod(id,action){if(action=='ban'&&!confirm('Ban/remove this member?'))return;if(action=='delete'&&!confirm('Delete this content?'))return;try{await api('/admin/moderation/'+id,{body:{action}});toast('Done');vAdmin()}catch(e){toast(e.message)}}
async function vAdmin(){const l=await api('/admin/reports');const mq=await api('/admin/moderation').catch(()=>[]);shell('Reports (admin)',`<h3 class="pad" style="margin:0;padding-bottom:0">🛡 Moderation queue (${mq.filter(x=>['pending','flagged','photo'].includes(x.status)).length})</h3><p class="pad muted" style="padding-top:2px;font-size:12px">Photos are not auto-scanned (text in photos isn't scanned either) – photo uploads are listed here for manual spot-checks.</p>`+(mq.length?mq.map(f=>`<div class="card pad"><b>${esc(f.category||'Flag')}</b> <span class="chip ${f.status=='pending'?'demo':''}">${f.status}</span> <span class="muted">${esc(f.kind)} · score ${f.score} · ${new Date(f.at).toLocaleString()}</span><div>By: <b>${esc(f.author?.name||'')}</b>${f.terms?.length?`<div class="muted">Matched: ${esc(f.terms.join(', '))}</div>`:''}<div style="white-space:pre-wrap;margin:6px 0">${esc(f.text||'')}</div>${f.photos?`<div class="gal">${f.photos.map(x=>`<img src="${x}" style="max-height:100px">`).join('')}</div>`:''}${f.contextUrl?`<a class="btn sm sec" href="${f.contextUrl}">View in context</a>`:''}
 ${['pending','flagged','photo'].includes(f.status)?`<button class="btn sm" onclick="admMod(${f.id},'approve')">Approve / release</button><button class="btn sm red" onclick="admMod(${f.id},'delete')">Delete content</button><button class="btn sm sec" onclick="admMod(${f.id},'warn')">Warn member</button><button class="btn sm red" onclick="admMod(${f.id},'ban')">Ban member</button>`:''}</div>`).join(''):'<p class="pad muted">Queue empty.</p>')+`<h3 class="pad" style="margin:0;padding-bottom:0">🚩 Reports</h3>`+(l.length?l.map(x=>`<div class="card pad"><b>${esc(x.reason)}</b> <span class="chip ${x.status=='open'?'demo':''}">${x.status}</span><div class="muted">${new Date(x.at).toLocaleString()} · by ${esc(x.byUser?.name)}</div>
 <div>Against: <b>${esc(x.againstUser?.name)}</b> (${esc(x.againstUser?.email)}) · strikes ${x.againstUser?.strikes}${x.againstUser?.banned?' · <b style="color:#e53935">REMOVED</b>':''}</div>${x.note?`<p>${esc(x.note)}</p>`:''}${x.swapId?`<div class="muted">Swap #${x.swapId}</div>`:''}
 ${x.status=='open'?`<button class="btn sm sec" onclick="adm(${x.id},'resolve')">Mark resolved</button>${x.againstUser?.banned?'':`<button class="btn sm red" onclick="adm(${x.id},'remove')">Remove member</button>`}`:''}</div>`).join(''):'<p class="pad muted">No reports.</p>'),'profile',1)}
async function adm(id,action){if(action=='remove'&&!confirm('Remove this member?'))return;await api('/admin/reports/'+id,{body:{action}});vAdmin()}
const invLink=()=>location.origin+'/join?ref='+(ME?.inviteCode||'');
function shareSheet(text,url=invLink()){const m=document.createElement('div');m.className='modal';const t=encodeURIComponent(text),u=encodeURIComponent(url);
 m.innerHTML=`<div><h3>Share</h3><p class="muted" style="word-break:break-all">${esc(url)}</p>${navigator.share?'<button class="btn" id="sn">📤 Share… (Instagram, etc.)</button>':''}
 <a class="btn sec" target="_blank" href="https://wa.me/?text=${t}%20${u}">WhatsApp</a><a class="btn sec" target="_blank" href="https://twitter.com/intent/tweet?text=${t}&url=${u}">X (Twitter)</a>
 <a class="btn sec" target="_blank" href="https://www.facebook.com/sharer/sharer.php?u=${u}">Facebook</a><button class="btn sec" id="sc">📋 Copy link</button><button class="btn sec" id="sx">Close</button></div>`;document.body.append(m);
 m.onclick=e=>{if(e.target==m)m.remove()};m.querySelector('#sx').onclick=()=>m.remove();
 m.querySelector('#sc').onclick=async()=>{try{await navigator.clipboard.writeText(url)}catch(e){const i=document.createElement('textarea');i.value=url;document.body.append(i);i.select();document.execCommand('copy');i.remove()}toast('Link copied')};
 const sn=m.querySelector('#sn');sn&&(sn.onclick=async()=>{try{await navigator.share({title:'Bud Share - craft growers network',text,url})}catch(e){}})}
const lockMsg=()=>`<div class="lock"><span>🔒</span><h2>Growers only</h2><p class="muted">Bud Share is a grower-to-grower network. List at least one of your own strains to browse other growers and request swaps.</p><a class="btn" href="#/strains/new">+ List your first strain</a></div>`;
const terms=`<div class="pad"><h2>Bud Share terms</h2><div class="disc">⚠️ ${DISC}</div><ol>
<li><b>Members must be 18 or older.</b> You confirm your date of birth when you join.</li>
<li><b>No sales, no money.</b> Bud Share is for swapping home-grown flower between private growers only. Any request for money, payment or anything of monetary value is banned and gets you removed.</li>
<li><b>Private use only.</b> Flower received is for your own private, personal use. You are responsible for complying with South African law, including the Cannabis for Private Purposes Act, and with your courier's terms.</li>
<li><b>Growers only.</b> You must have at least one of your own strains listed to swap.</li>
<li><b>Honest dealing.</b> Send what you agreed and share real tracking details. If a partner reports your parcel as not received 3 times, your account is deleted.</li>
<li>Ratings must be honest and only come from members who actually received the flower.</li>
<li>Bud Share is a meeting place for growers and does not handle, check or transport any product.</li></ol></div>`;
// ---------- in-app photo / COA viewer (overlay; never navigates away)
let viewerOn=false;
function openViewer(src){if(!src)return;closeViewer(1);viewerOn=true;const isPdf=/\.pdf($|\?)/i.test(src);
 const v=document.createElement('div');v.className='viewer';v.id='viewer';
 v.innerHTML=`<div class="vbar"><button type="button" class="vbtn" id="vback" aria-label="Back">←</button><span class="vt">${isPdf||/coa/i.test(src)?'Certificate of Analysis':'Photo'}</span><button type="button" class="vbtn" id="vclose" aria-label="Close">✕</button></div><div class="vbody">${isPdf?`<iframe src="${esc(src)}" title="COA"></iframe>`:`<img src="${esc(src)}" alt="">`}</div>`;
 document.body.append(v);document.body.style.overflow='hidden';
 try{history.pushState({bsViewer:1},'')}catch(e){}
 const done=()=>closeViewer();v.querySelector('#vclose').onclick=()=>{if(history.state&&history.state.bsViewer)history.back();else closeViewer()};
 v.querySelector('#vback').onclick=v.querySelector('#vclose').onclick;
 v.querySelector('.vbody').onclick=e=>{if(e.target.classList.contains('vbody')){if(history.state&&history.state.bsViewer)history.back();else closeViewer()}}}
function closeViewer(silent){const v=document.getElementById('viewer');if(v)v.remove();if(viewerOn){viewerOn=false;document.body.style.overflow=''}}
addEventListener('popstate',()=>{if(viewerOn)closeViewer()});
addEventListener('keydown',e=>{if(e.key=='Escape'&&viewerOn){if(history.state&&history.state.bsViewer)history.back();else closeViewer()}});
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-view]');if(t){e.preventDefault();e.stopPropagation();openViewer(t.dataset.view||t.getAttribute('src'))}});
// ---------- auth
async function vAuth(mode='login'){await geo();A.innerHTML=`<div class="hero"><img src="/icon-192.png" width="72" style="border-radius:16px"><h1>Bud Share</h1><div style="opacity:.9">craft growers network</div><div style="font-size:12px;margin-top:6px;display:flex;align-items:center;justify-content:center;gap:6px"><span>By</span><img src="/whoomph-logo-b70b4539.png" alt="Whoomph" style="height:26px"></div><div style="margin-top:10px;font-size:14px">Grower-to-grower swaps · 18+ · No sales</div></div>
<div class="tabs2"><a href="#/login" class="${mode=='login'?'on':''}">Log in</a><a href="#/signup" class="${mode=='signup'?'on':''}">Join</a></div><form class="pad" id="f">
${mode=='signup'?`<label>Display name</label><input name="name" required><label>Date of birth (must be 18+)</label><input type="date" name="dob" required>
${locFields()}<input name="town" required>`:''}
${mode=='signup'&&REF?`<div class="chip" style="margin-top:12px">🤝 Invited by ${esc(REFNAME||REF)}</div><input type="hidden" name="ref" value="${esc(REF)}">`:''}<label>Email</label><input type="text" inputmode="email" autocapitalize="none" autocorrect="off" spellcheck="false" name="email" required autocomplete="username"><label>Password</label><input type="password" name="password" required minlength="6">
${mode=='signup'?`<div class="chk"><input type="checkbox" name="agree" id="ag" required><label for="ag" style="margin:0">I am 18+ and I agree to the <a href="/terms" target="_blank" rel="noopener">Terms</a> and <a href="/privacy" target="_blank" rel="noopener">Privacy Policy</a> (no sales, no money, private use)</label></div>${discBox()}<div class="chk"><input type="checkbox" name="agreeRisk" id="ag2" required><label for="ag2" style="margin:0">I understand and agree: I swap at my own risk and only where it is legal for me</label></div>`:''}
<button class="btn">${mode=='signup'?'Create account':'Log in'}</button></form><p class="pad muted legalfoot"><a href="/terms" target="_blank" rel="noopener">Terms of Use</a> · <a href="/privacy" target="_blank" rel="noopener">Privacy Policy</a></p>`;
 bindLoc();$('#f').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.agree=!!d.agree;d.agreeRisk=!!d.agreeRisk;try{await api('/'+mode,{body:d});if(mode=='signup')localStorage.removeItem('bs_ref');await loadMe();location.hash='#/browse'}catch(x){toast(x.message)}}}
let REF=new URLSearchParams(location.search).get('ref')||localStorage.getItem('bs_ref')||'',REFNAME='';if(REF){localStorage.setItem('bs_ref',REF);fetch('/api/invite/'+encodeURIComponent(REF)).then(r=>r.json()).then(j=>{REFNAME=j.name||'';if(location.hash=='#/signup')vAuth('signup')});if(location.pathname=='/join'||location.search){history.replaceState(null,'','/'+(location.hash||'#/signup'))}}
async function loadMe(){try{ME=await api('/me');const s=await api('/swaps');ME.unread=s.reduce((a,b)=>a+b.unread,0)}catch(e){ME=null}}
// ---------- follows
let FOL=null,FOLLIST=[];
async function loadFol(){if(FOL)return;try{FOLLIST=await api('/following');FOL=new Set(FOLLIST.map(x=>x.user.id))}catch(e){FOL=new Set()}}
const folBtn=(u,cls='')=>{if(!u||!ME||u.id==ME.id)return'';const on=FOL&&FOL.has(u.id);return `<button class="btn sm ${on?'':'sec'} folbtn ${cls}" data-fol="${u.id}">${on?'✓ Following':'＋ Follow grower'}</button>`};
function bindFol(root=document){root.querySelectorAll('[data-fol]').forEach(b=>{if(b._fb)return;b._fb=1;b.onclick=async e=>{e.preventDefault();e.stopPropagation();const id=+b.dataset.fol;try{const r=await api(`/users/${id}/follow`,{body:{}});FOL=FOL||new Set();r.following?FOL.add(id):FOL.delete(id);FOLLIST=[];
 document.querySelectorAll(`[data-fol="${id}"]`).forEach(x=>{x.textContent=r.following?'✓ Following':'＋ Follow grower';x.classList.toggle('sec',!r.following)});document.querySelectorAll(`[data-fcount="${id}"]`).forEach(x=>x.textContent=r.followerCount);toast(r.following?'Following grower 🌱':'Unfollowed')}catch(x){toast(x.message)}}})}
const lastAct=u=>{if(!u.lastSeen)return'';const m=(Date.now()-u.lastSeen)/60000;return m<5?' · 🟢 Online':m<60?` · Last active ${Math.floor(m)}m ago`:m<1440?` · Last active ${Math.floor(m/60)}h ago`:` · Last active ${Math.floor(m/1440)}d ago`};
const folCounts=u=>`<span class="muted"><b data-fcount="${u.id}">${u.followerCount||0}</b> followers · <b>${u.followingCount||0}</b> following</span>`;
const mutualTag=u=>u.iFollow&&u.followsMe?' <span class="chip v18">🤝 Mutual</span>':u.followsMe?' <span class="chip v18">Follows you</span>':'';
// ---------- browse
let F={sort:'near'},VIEW='feed';
async function vBrowse(){await geo();await loadFol();shell('Bud Share',`<div class="browsehead"><div class="tabs2"><a href="javascript:VIEW='feed';vBrowse()" class="${VIEW=='feed'?'on':''}">📰 Feed</a><a href="javascript:VIEW='strains';vBrowse()" class="${VIEW=='strains'?'on':''}">${LEAF()} Strains</a></div>`+`<div class="searchbar"><span>🔍</span><input id="fq" placeholder="Search strains, e.g. Northern Lights…" value="${esc(F.q||'')}" autocomplete="off" enterkeyhint="search"><button type="button" id="fx" aria-label="Clear search" style="${F.q?'':'display:none'}">✕</button></div><div class="filters">
<select id="fc">${opts(GEO.countries,F.country,'All countries')}</select>${F.country&&AREAS(F.country).length?`<select id="fp">${opts(AREAS(F.country),F.province,'All areas')}</select>`:F.country?`<input id="fp" placeholder="Area" value="${esc(F.province||'')}" style="width:100px;font-size:14px;padding:7px;border-radius:16px">`:''}<select id="ft">${opts(META.types,F.type,'All types')}</select><select id="fm">${opts(META.methods,F.method,'Any method')}</select>
<select id="fo"><option value="">Organic?</option><option value="1" ${F.organic?'selected':''}>Organic only</option></select>
<input id="fw" placeholder="Town" value="${esc(F.town||'')}" style="width:110px;font-size:14px;padding:7px;border-radius:16px"><select id="fl"><option value="">Any</option><option value="1" ${F.lab?'selected':''}>Lab tested</option></select>
<select id="fr"><option value="">Any rating</option><option value="3" ${F.minrating==3?'selected':''}>3★+</option><option value="4" ${F.minrating==4?'selected':''}>4★+</option><option value="4.5" ${F.minrating==4.5?'selected':''}>4.5★+</option></select><button type="button" id="ffol" class="btn sm ${F.following?'':'sec'}" style="flex:0 0 auto">🌱 Following</button><select id="fs">${VIEW=='feed'?'<option value="new">Newest</option>':''}<option value="near" ${VIEW=='feed'&&F.sort=='near'?'selected':''}>Nearest first</option><option value="rating" ${F.sort=='rating'?'selected':''}>Highest rated</option></select></div></div><div id="rcount"></div>${VIEW=='feed'?'<div id="comp"></div><div id="list"></div>':'<div id="list" class="grid"></div>'}`,'browse');
 const hd=document.querySelector('header');if(hd)document.documentElement.style.setProperty('--hh',hd.offsetHeight+'px');let dbt;const fq=$('#fq');fq.oninput=e=>{F.q=e.target.value;$('#fx').style.display=F.q?'':'none';clearTimeout(dbt);dbt=setTimeout(load,250)};fq.onkeydown=e=>{if(e.key=='Enter')e.preventDefault()};$('#fx').onclick=()=>{fq.value='';F.q='';$('#fx').style.display='none';load();fq.focus()};
 $('#ffol').onclick=e=>{F.following=F.following?'':1;e.target.classList.toggle('sec',!F.following);load()};const map={ft:'type',fm:'method',fo:'organic',fl:'lab',fs:'sort',fr:'minrating'};$('#fc').onchange=e=>{F.country=e.target.value;delete F.province;vBrowse()};$('#fp')&&($('#fp').onchange=e=>{F.province=e.target.value;load()});$('#fw').onchange=e=>{F.town=e.target.value;load()};Object.entries(map).forEach(([i,k])=>$('#'+i).onchange=e=>{F[k]=e.target.value;load()});
 async function load(){if(VIEW=='feed')return loadFeed();try{const l=await api('/browse?'+new URLSearchParams(Object.fromEntries(Object.entries(F).filter(x=>x[1]))));
  const rc=$('#rcount');if(rc)rc.innerHTML=F.q?`<b>${new Set(l.map(x=>x.userId)).size}</b> grower${new Set(l.map(x=>x.userId)).size==1?'':'s'} offering &ldquo;${esc(F.q.trim())}&rdquo;${l.length!=new Set(l.map(x=>x.userId)).size?` · ${l.length} listings`:''}`:'';
  $('#list').innerHTML=l.length?l.map(s=>`<a class="tile" href="#/strain/${s.id}"><img src="${s.flowerPhotos[0]}" loading="lazy"><div><div class="t1">${LEAF()} ${esc(s.name)}</div>
  <div class="muted">${esc(s.type)} · ${s.method}${s.organic?' · Organic':''}</div><div class="chips">${s.labTested?'<span class="chip lab">🧪 Lab tested</span>':''}${s.demo?'<span class="chip demo">DEMO</span>':''}</div>
  <div class="muted">${esc(s.owner.name)} ${s.owner.rating?`<span class="stars">★</span>${s.owner.rating}`:''}</div><div class="muted">📍 ${loc(s.owner)} · ${s.distance}</div><div class="muted">🤝 Swap amount negotiable</div>${folBtn(s.owner)}</div></a>`).join(''):`<p class="pad muted">${F.q?`No one is offering &ldquo;${esc(F.q.trim())}&rdquo; yet — try another spelling or clear filters.`:'No strains match these filters.'}</p>`;bindFol($('#list'))}
  catch(e){if(e.code=='grower_only')$('#list').outerHTML=lockMsg();else toast(e.message)}}
 async function loadFeed(){try{let l=await api('/feed?'+new URLSearchParams(Object.fromEntries(Object.entries(F).filter(x=>x[1]&&x[1]!='new'))));
  $('#comp').innerHTML=`<div class="card pad" style="padding:12px"><div style="display:flex;gap:10px">${av(ME,'s')}<button class="btn sec" style="margin:0;text-align:left;color:var(--m);border-color:#ccd" id="np">Share your grow, flower or tips…</button></div></div>`;$('#np').onclick=newPost;
  l=l.filter((p,i)=>l.findIndex(x=>x.id==p.id)==i);const rc=$('#rcount');if(rc)rc.innerHTML=F.q?`<b>${l.length}</b> post${l.length==1?'':'s'} · <b>${new Set(l.map(x=>x.userId)).size}</b> grower${new Set(l.map(x=>x.userId)).size==1?'':'s'} for &ldquo;${esc(F.q.trim())}&rdquo;`:'';
  $('#list').innerHTML=l.length?l.map(postHTML).join(''):'<p class="pad muted">'+(F.q?`No one is offering &ldquo;${esc(F.q.trim())}&rdquo; yet — try another spelling or clear filters.`:F.following?'No posts from growers you follow yet.':'No posts match.')+'</p>';bindPosts(loadFeed);bindFol($('#list'))}
  catch(e){if(e.code=='grower_only'){$('#comp').innerHTML='';$('#list').innerHTML=lockMsg()}else toast(e.message)}}
 load()}
const ago=t=>{const m=(Date.now()-t)/6e4;return m<1?'now':m<60?Math.floor(m)+'m':m<1440?Math.floor(m/60)+'h':Math.floor(m/1440)+'d'};
const postHTML=p=>`<div class="card" data-p="${p.id}"><a class="row" style="border:0" href="#/user/${p.author.id}">${av(p.author,'s')}<div class="grow"><div class="t1">${esc(p.author.name)} ${p.author.rating?`<span class="stars">★</span><small>${p.author.rating}</small>`:''}</div><div class="t2">📍 ${esc(p.author.town)} · ${ago(p.at)}</div></div>${folBtn(p.author)}</a>
 ${p.text?`<div style="padding:0 16px 10px;white-space:pre-wrap">${esc(p.text)}</div>`:''}${p.photos.length?`<div class="gal">${p.photos.map(x=>`<img src="${x}" loading="lazy" data-view="${x}">`).join('')}</div>`:''}
 ${p.strain?`<a class="row" href="#/strain/${p.strain.id}" style="background:#f7faf8"><div class="grow"><b>${LEAF()} ${esc(p.strain.name)}</b><div class="chips"><span class="chip">${esc(p.strain.type)}</span><span class="chip">${p.strain.method}</span>${p.strain.organic?'<span class="chip">Organic</span>':''}${p.strain.labTested?'<span class="chip lab">🧪 Lab tested</span>':''}</div></div>${p.userId!=ME.id?'<span class="btn sm" style="margin:0">⇄ Swap</span>':'›'}</a>`:''}
 ${p.held?'<div style="padding:4px 16px"><span class="chip demo">⏳ Held for review – only you can see this post</span></div>':''}<div style="display:flex;gap:4px;padding:6px 10px;border-top:1px solid var(--b)"><button class="btn sm sec lk" style="border:0;${p.liked?'color:#e53935':''}">${p.liked?'❤️':'🤍'} ${p.likes}</button><button class="btn sm sec cm" style="border:0">💬 ${p.comments}</button><button class="btn sm sec sh" style="border:0">📤</button>${p.userId==ME.id?'<button class="btn sm sec dl" style="border:0;margin-left:auto">🗑</button>':''}</div></div>`;
function bindPosts(reload){document.querySelectorAll('[data-p]').forEach(el=>{const id=el.dataset.p;
 el.querySelector('.lk').onclick=async()=>{await api(`/posts/${id}/like`,{body:{}});reload()};
 el.querySelector('.cm').onclick=()=>commentsModal(id,reload);el.querySelector('.sh').onclick=()=>{const t=el.querySelector('.row .t1')?.innerText||'';shareSheet(`${t.split(' ★')[0]} shared a post on Bud Share – craft growers network (18+, swaps only)`)};const d=el.querySelector('.dl');d&&(d.onclick=async()=>{if(confirm('Delete post?')){await api(`/posts/${id}/delete`,{body:{}});reload()}})})}
async function commentsModal(id,reload){const c=await api(`/posts/${id}/comments`);modal(`<h3>Comments</h3>${c.length?c.map(x=>`<div class="row" style="padding:8px 0">${av(x.author,'s')}<div class="grow"><b>${esc(x.author.name)}</b> <span class="muted">${ago(x.at)}</span><div>${esc(x.text)}</div></div></div>`).join(''):'<p class="muted">No comments yet.</p>'}<label>Add a comment</label><input name="text" required>`,'Post comment',async d=>{await api(`/posts/${id}/comments`,{body:d});reload()})}
async function shrink(f){if(!/^image\/(jpeg|png|webp|heic)/.test(f.type)||f.size<400e3)return f;try{const b=await createImageBitmap(f),k=Math.min(1,1600/Math.max(b.width,b.height)),c=document.createElement('canvas');c.width=b.width*k;c.height=b.height*k;c.getContext('2d').drawImage(b,0,0,c.width,c.height);
 const bl=await new Promise(r=>c.toBlob(r,'image/jpeg',.85));return bl&&bl.size<f.size?new File([bl],f.name.replace(/\.\w+$/,'')+'.jpg',{type:'image/jpeg'}):f}catch(e){return f}}
async function shrinkForm(form){const fd=new FormData();for(const[k,v]of new FormData(form))fd.append(k,v instanceof File&&v.size?await shrink(v):v);for(const[k,v]of[...fd])if(v instanceof File&&!v.size)fd.delete(k);return fd}
function newPost(){if(document.querySelector('.modal'))return;const m=document.createElement('div');m.className='modal';const cid=(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random());m.innerHTML=`<div><form><h3>New post</h3><textarea name="text" placeholder="Your flower, grow style, tips…"></textarea><label>📸 Photos (as many as you like)</label><input type="file" name="photos" accept="image/*" multiple><button class="btn" id="pb">Post</button><button type="button" class="btn sec" id="mx">Cancel</button></form></div>`;document.body.append(m);
 let busy=false;m.querySelector('#mx').onclick=()=>m.remove();m.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=m.querySelector('#pb');b.disabled=true;b.textContent='Posting…';
  try{const fd=new FormData();fd.set('text',e.target.text.value);fd.set('clientId',cid);for(const f of e.target.photos.files)fd.append('photos',await shrink(f));const pr=await api('/posts',{body:fd});m.remove();VIEW='feed';vBrowse();if(pr.held)toast('⏳ Held for review – our team will check it shortly')}catch(x){toast(x.message);busy=false;b.disabled=false;b.textContent='Post'}}}
